CREATE OR REPLACE FUNCTION platform.guard_adaptive_attempt_child()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE attempt platform.baseline_adaptive_attempt%ROWTYPE;
DECLARE item platform.baseline_attempt_item%ROWTYPE;
BEGIN
    IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND TG_TABLE_NAME <> 'baseline_attempt_skill_state') THEN
        RAISE EXCEPTION 'Adaptive child history is immutable' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO STRICT attempt FROM platform.baseline_adaptive_attempt WHERE attempt_id = NEW.attempt_id FOR UPDATE;
    IF TG_TABLE_NAME IN ('baseline_attempt_result', 'baseline_attempt_skill_result', 'baseline_mastery_evidence') THEN
        IF attempt.state = 'INVALIDATED' THEN
            RAISE EXCEPTION 'Invalidated attempts produce no result or mastery' USING ERRCODE = '23514';
        END IF;
        RETURN NEW; -- Deferred completeness checks allow finalization in either write order.
    END IF;
    IF attempt.state <> 'IN_PROGRESS' THEN
        RAISE EXCEPTION 'Terminal attempts accept no mutable child state' USING ERRCODE = '23514';
    END IF;
    IF TG_TABLE_NAME = 'baseline_attempt_pool_item' OR
        (TG_TABLE_NAME = 'baseline_attempt_skill_state' AND TG_OP = 'INSERT') THEN
        IF attempt.revision <> 1 OR EXISTS (SELECT 1 FROM platform.baseline_attempt_item WHERE attempt_id = NEW.attempt_id) THEN
            RAISE EXCEPTION 'Starting pool/skill membership is sealed by the first item' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_TABLE_NAME = 'baseline_attempt_skill_state' THEN
        IF NEW.revision <> OLD.revision + 1 OR NEW.answered_count <> OLD.answered_count + 1
            OR ROW(NEW.attempt_id, NEW.organization_id, NEW.micro_skill_id)
                IS DISTINCT FROM ROW(OLD.attempt_id, OLD.organization_id, OLD.micro_skill_id) THEN
            RAISE EXCEPTION 'Skill state requires same identity and next answer revision' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_TABLE_NAME = 'baseline_attempt_item' THEN
        IF NEW.position > attempt.max_questions OR NEW.presented_at < attempt.started_at
            OR NEW.presented_at >= attempt.deadline_at
            OR NEW.position <> (SELECT count(*) + 1 FROM platform.baseline_attempt_item WHERE attempt_id = NEW.attempt_id)
            OR (NEW.position > 1 AND NOT EXISTS (SELECT 1 FROM platform.baseline_attempt_response
                WHERE attempt_id = NEW.attempt_id AND position = NEW.position - 1 AND accepted_at <= NEW.presented_at)) THEN
            RAISE EXCEPTION 'Presentation must be next, unseen and within bounds/deadline' USING ERRCODE = '23514';
        END IF;
        IF EXISTS (
            WITH expected AS (SELECT option ->> 'id' AS id FROM platform.item_version version,
                jsonb_array_elements(version.response_schema -> 'options') option WHERE version.item_version_id = NEW.item_version_id),
            actual AS (SELECT jsonb_array_elements_text(NEW.option_order) AS id)
            (SELECT * FROM expected EXCEPT SELECT * FROM actual) UNION ALL
            (SELECT * FROM actual EXCEPT SELECT * FROM expected)) THEN
            RAISE EXCEPTION 'Option order must contain exactly the pinned item options' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_TABLE_NAME = 'baseline_attempt_response' THEN
        SELECT * INTO STRICT item FROM platform.baseline_attempt_item
            WHERE attempt_id = NEW.attempt_id AND position = NEW.position;
        IF NEW.accepted_at < item.presented_at OR NEW.accepted_at >= attempt.deadline_at
            OR jsonb_typeof(NEW.response_payload -> 'selectedOptionId') IS DISTINCT FROM 'string'
            OR NOT (item.option_order ? (NEW.response_payload ->> 'selectedOptionId')) THEN
            RAISE EXCEPTION 'Response must select a presented option strictly before deadline' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_adaptive_attempt_header()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE blueprint platform.baseline_adaptive_blueprint_version%ROWTYPE;
DECLARE prior platform.baseline_adaptive_attempt%ROWTYPE;
DECLARE bounds record;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Adaptive attempt history cannot be deleted' USING ERRCODE = '23514';
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.state <> 'IN_PROGRESS' OR NEW.revision <> OLD.revision + 1
            OR (to_jsonb(NEW) - ARRAY['state','revision','finished_at','completion_reason'])
                IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['state','revision','finished_at','completion_reason']) THEN
            RAISE EXCEPTION 'Attempt is terminal, stale or pinned inputs changed' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.state <> 'IN_PROGRESS' OR NEW.revision <> 1 THEN
        RAISE EXCEPTION 'Attempts must start in progress at revision one' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO STRICT blueprint FROM platform.baseline_adaptive_blueprint_version
        WHERE blueprint_id = NEW.blueprint_id AND version = NEW.blueprint_version;
    IF ROW(NEW.model_version_id, NEW.mastery_mapping_version_id, NEW.parameter_set_id, NEW.catalog_fingerprint)
        IS DISTINCT FROM ROW(blueprint.model_version_id, blueprint.mastery_mapping_version_id,
            blueprint.parameter_set_id, blueprint.catalog_fingerprint) THEN
        RAISE EXCEPTION 'Attempt technical/catalog pins must match Blueprint' USING ERRCODE = '23514';
    END IF;
    IF NEW.scope_policy IS DISTINCT FROM blueprint.scope_policy THEN
        RAISE EXCEPTION 'Attempt scope policy must match its immutable Blueprint' USING ERRCODE = '23514';
    END IF;
    IF blueprint.scope_policy = 'FULL_OCCUPATION_V2' THEN
        SELECT blueprint.occupation_max_questions AS maximum,
            blueprint.occupation_time_limit_seconds AS duration INTO bounds;
    ELSIF NEW.target_role_id IS NULL THEN
        SELECT blueprint.exploration_max_questions AS maximum,
            blueprint.exploration_time_limit_seconds AS duration INTO bounds;
    ELSE
        SELECT max_questions AS maximum, time_limit_seconds AS duration INTO STRICT bounds
            FROM platform.baseline_adaptive_blueprint_role WHERE blueprint_id = NEW.blueprint_id
                AND blueprint_version = NEW.blueprint_version AND role_id = NEW.target_role_id;
    END IF;
    IF ROW(NEW.max_questions, NEW.time_limit_seconds) IS DISTINCT FROM ROW(bounds.maximum, bounds.duration) THEN
        RAISE EXCEPTION 'Attempt bounds must match its pinned purpose/role' USING ERRCODE = '23514';
    END IF;
    IF NEW.replaces_attempt_id IS NOT NULL THEN
        SELECT * INTO STRICT prior FROM platform.baseline_adaptive_attempt
            WHERE attempt_id = NEW.replaces_attempt_id FOR UPDATE;
        IF prior.state <> 'INVALIDATED' OR prior.finished_at > NEW.started_at
            OR ROW(prior.organization_id, prior.learner_id, prior.occupation_id)
                IS DISTINCT FROM ROW(NEW.organization_id, NEW.learner_id, NEW.occupation_id) THEN
            RAISE EXCEPTION 'Only same-scope invalidated history may be replaced' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_adaptive_membership_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM 1 FROM platform.baseline_adaptive_blueprint_version
    WHERE blueprint_id = NEW.blueprint_id AND version = NEW.blueprint_version FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Adaptive parent version must be visible before membership' USING ERRCODE = '23503';
    END IF;
    IF EXISTS (SELECT 1 FROM platform.baseline_blueprint_activation_event
        WHERE blueprint_id = NEW.blueprint_id AND blueprint_version = NEW.blueprint_version) THEN
        RAISE EXCEPTION 'Finalized Blueprint membership is immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_TABLE_NAME = 'baseline_adaptive_blueprint_role' THEN
        IF EXISTS (SELECT 1 FROM platform.baseline_adaptive_blueprint_version parent
            WHERE parent.blueprint_id = NEW.blueprint_id AND parent.version = NEW.blueprint_version
              AND ((parent.scope_policy IS NULL AND (NEW.max_questions IS NULL OR NEW.time_limit_seconds IS NULL))
                OR (parent.scope_policy = 'FULL_OCCUPATION_V2' AND (NEW.max_questions IS NOT NULL OR NEW.time_limit_seconds IS NOT NULL)))) THEN
            RAISE EXCEPTION 'Role bounds must match the pinned Blueprint scope policy' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_adaptive_working_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' OR OLD.state <> 'OPEN' THEN
        RAISE EXCEPTION 'Closed adaptive working revision is immutable' USING ERRCODE = '23514';
    END IF;
    IF (to_jsonb(NEW) - ARRAY['revision', 'configuration', 'state', 'updated_by', 'updated_at', 'closed_at'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['revision', 'configuration', 'state', 'updated_by', 'updated_at', 'closed_at'])
        OR NEW.revision <> OLD.revision + 1 THEN
        RAISE EXCEPTION 'Adaptive revision requires stable identity and next revision' USING ERRCODE = '23514';
    END IF;
    IF (OLD.configuration ? 'occupationBounds') IS DISTINCT FROM (NEW.configuration ? 'occupationBounds') THEN
        RAISE EXCEPTION 'Archive the legacy Draft before creating a new-format Draft' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_baseline_activation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Disable availability rather than deleting the pointer' USING ERRCODE = '23514';
    ELSIF TG_OP = 'INSERT' THEN
        IF NEW.activation_revision <> 1 OR NEW.blueprint_version IS NULL THEN
            RAISE EXCEPTION 'First activation requires version and revision one' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.organization_id <> OLD.organization_id OR NEW.occupation_id <> OLD.occupation_id
        OR NEW.blueprint_id <> OLD.blueprint_id OR NEW.activation_revision <> OLD.activation_revision + 1 THEN
        RAISE EXCEPTION 'Activation requires stable scope and next revision' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_baseline_version_namespace()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM 1 FROM platform.baseline_blueprint WHERE blueprint_id = NEW.blueprint_id FOR UPDATE;
    INSERT INTO platform.baseline_blueprint_version_registry(blueprint_id, version, contract_family)
    VALUES (NEW.blueprint_id, NEW.version,
        CASE WHEN TG_TABLE_NAME = 'baseline_blueprint_version' THEN 'FIXED' ELSE 'ADAPTIVE' END);
    IF TG_TABLE_NAME = 'baseline_adaptive_blueprint_version' THEN
        IF NOT EXISTS (SELECT 1 FROM platform.irt_parameter_set
            WHERE parameter_set_id = NEW.parameter_set_id AND status = 'PROMOTED') THEN
            RAISE EXCEPTION 'New Blueprint requires a promoted parameter set' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_baseline_working_namespace()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM 1 FROM platform.baseline_blueprint WHERE blueprint_id = NEW.blueprint_id FOR UPDATE;
    IF TG_OP = 'INSERT' THEN
        IF TG_TABLE_NAME = 'baseline_adaptive_blueprint_working_revision'
            AND (NEW.state <> 'OPEN' OR NEW.revision <> 1) THEN
            RAISE EXCEPTION 'Adaptive working revision must start open at revision one' USING ERRCODE = '23514';
        END IF;
        IF NEW.state = 'OPEN' THEN
            INSERT INTO platform.baseline_blueprint_working_registry(blueprint_id, working_revision_id, contract_family)
            VALUES (NEW.blueprint_id, NEW.working_revision_id,
                CASE WHEN TG_TABLE_NAME = 'baseline_blueprint_working_revision' THEN 'FIXED' ELSE 'ADAPTIVE' END);
        END IF;
    ELSE
        IF NEW.blueprint_id <> OLD.blueprint_id OR NEW.working_revision_id <> OLD.working_revision_id
            OR NEW.organization_id <> OLD.organization_id OR NEW.occupation_id <> OLD.occupation_id THEN
            RAISE EXCEPTION 'Working revision scope is immutable' USING ERRCODE = '23514';
        END IF;
        IF OLD.state = 'OPEN' AND NEW.state <> 'OPEN' THEN
            DELETE FROM platform.baseline_blueprint_working_registry
            WHERE blueprint_id = OLD.blueprint_id AND working_revision_id = OLD.working_revision_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_closed_baseline_working_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' OR OLD.state <> 'OPEN' THEN
        RAISE EXCEPTION 'Baseline working revision history is immutable'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_irt_calibration_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        PERFORM 1 FROM platform.model_version WHERE model_version_id = NEW.model_version_id FOR SHARE;
        IF NEW.status <> 'PENDING' THEN
            RAISE EXCEPTION 'Calibration must start pending' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' OR OLD.status IN ('SUCCEEDED', 'FAILED') THEN
        RAISE EXCEPTION 'Completed calibration history is immutable' USING ERRCODE = '23514';
    END IF;
    IF (to_jsonb(NEW) - ARRAY['status', 'output_parameter_set_id', 'diagnostics', 'started_at', 'completed_at'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status', 'output_parameter_set_id', 'diagnostics', 'started_at', 'completed_at'])
        OR NOT ((OLD.status = 'PENDING' AND NEW.status = 'RUNNING')
            OR (OLD.status = 'RUNNING' AND NEW.status IN ('RUNNING', 'SUCCEEDED', 'FAILED')))
        OR (OLD.status = 'RUNNING' AND NEW.started_at IS DISTINCT FROM OLD.started_at) THEN
        RAISE EXCEPTION 'Invalid calibration transition' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'SUCCEEDED' AND NOT EXISTS (SELECT 1 FROM platform.irt_parameter_set
        WHERE parameter_set_id = NEW.output_parameter_set_id AND source = 'CALIBRATED' AND status = 'CANDIDATE') THEN
        RAISE EXCEPTION 'Calibration output must be an immutable calibrated candidate' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_irt_model_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM platform.irt_parameter_set WHERE model_version_id = OLD.model_version_id)
        OR EXISTS (SELECT 1 FROM platform.irt_calibration_run WHERE model_version_id = OLD.model_version_id) THEN
        RAISE EXCEPTION 'IRT parameter sets pin immutable model configuration' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_irt_parameter_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE set_state text;
BEGIN
    SELECT status INTO set_state FROM platform.irt_parameter_set
    WHERE parameter_set_id = NEW.parameter_set_id FOR UPDATE;
    IF set_state IS DISTINCT FROM 'BUILDING' THEN
        RAISE EXCEPTION 'Sealed parameter content cannot be extended' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_irt_parameter_set()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- FOR SHARE also excludes concurrent non-key edits to the pinned configuration.
        PERFORM 1 FROM platform.model_version WHERE model_version_id = NEW.model_version_id FOR SHARE;
        IF NEW.status <> 'BUILDING' THEN
            RAISE EXCEPTION 'Parameter sets must be assembled before sealing' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Parameter set history is immutable' USING ERRCODE = '23514';
    ELSIF (to_jsonb(NEW) - ARRAY['status', 'activated_by', 'activated_at'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status', 'activated_by', 'activated_at'])
        OR NOT ((OLD.status = 'BUILDING' AND NEW.status = 'CANDIDATE')
            OR (OLD.status = 'CANDIDATE' AND NEW.status = 'PROMOTED')) THEN
        RAISE EXCEPTION 'Only seal or promote may change a parameter set' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_pathway_content()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Pathway revision history cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF (to_jsonb(NEW) - ARRAY['status', 'validation_status', 'published_at'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status', 'validation_status', 'published_at']) THEN
        RAISE EXCEPTION 'Pathway edits require a new revision' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_pathway_step_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE revision_state text;
BEGIN
    SELECT status INTO revision_state FROM platform.pathway_revision
        WHERE pathway_revision_id = NEW.pathway_revision_id FOR UPDATE;
    IF revision_state NOT IN ('GENERATED', 'IN_REVIEW') OR EXISTS (
        SELECT 1 FROM platform.pathway_approval WHERE pathway_revision_id = NEW.pathway_revision_id
    ) THEN
        RAISE EXCEPTION 'Cannot add steps to an approved pathway revision' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_published_children()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE old_parent uuid; new_parent uuid; parent_state text;
BEGIN
    IF TG_TABLE_NAME = 'assessment_item' THEN
        IF TG_OP <> 'INSERT' THEN old_parent := OLD.assessment_version_id; END IF;
        IF TG_OP <> 'DELETE' THEN new_parent := NEW.assessment_version_id; END IF;
        FOR parent_state IN SELECT publication_state FROM platform.assessment_version
            WHERE assessment_version_id IN (old_parent, new_parent) ORDER BY assessment_version_id FOR UPDATE
        LOOP
            IF parent_state = 'PUBLISHED' THEN
                RAISE EXCEPTION 'Published assessment item set is immutable' USING ERRCODE = '23514';
            END IF;
        END LOOP;
    ELSE
        IF TG_OP <> 'INSERT' THEN old_parent := OLD.item_version_id; END IF;
        IF TG_OP <> 'DELETE' THEN new_parent := NEW.item_version_id; END IF;
        FOR parent_state IN SELECT publication_state FROM platform.item_version
            WHERE item_version_id IN (old_parent, new_parent) ORDER BY item_version_id FOR UPDATE
        LOOP
            IF parent_state = 'PUBLISHED' THEN
                RAISE EXCEPTION 'Published item mapping set is immutable' USING ERRCODE = '23514';
            END IF;
        END LOOP;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_published_definition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP <> 'INSERT' AND OLD.publication_state = 'PUBLISHED' THEN
        RAISE EXCEPTION 'Published assessment definitions are immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;

    IF TG_TABLE_NAME = 'assessment_version' THEN
        IF TG_OP = 'UPDATE'
            AND OLD.reviewed_content_hash IS NOT NULL
            AND (to_jsonb(NEW) - 'publication_state' - 'baseline_candidate_state')
                IS DISTINCT FROM
                (to_jsonb(OLD) - 'publication_state' - 'baseline_candidate_state') THEN
            RAISE EXCEPTION 'Reviewed assessment content and review evidence are immutable'
                USING ERRCODE = '23514';
        END IF;
        IF NEW.blueprint_id IS NOT NULL
            AND NEW.publication_state = 'PUBLISHED'
            AND NEW.reviewed_content_hash IS DISTINCT FROM NEW.content_hash THEN
            RAISE EXCEPTION 'Generated baseline assessment must publish the reviewed content hash'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.publication_state = 'PUBLISHED' THEN
        IF TG_TABLE_NAME = 'item_version' THEN
            IF NEW.micro_skill_id IS NULL
                AND (SELECT coalesce(sum(evidence_weight), 0)
                    FROM platform.item_skill_mapping
                    WHERE item_version_id = NEW.item_version_id) <> 1 THEN
                RAISE EXCEPTION 'Published legacy item evidence weights must sum to one'
                    USING ERRCODE = '23514';
            END IF;
        ELSE
            IF NOT EXISTS (
                    SELECT 1 FROM platform.assessment_item
                    WHERE assessment_version_id = NEW.assessment_version_id AND required)
                OR EXISTS (
                    SELECT 1
                    FROM platform.assessment_item entry
                    JOIN platform.item_version item USING (item_version_id)
                    WHERE entry.assessment_version_id = NEW.assessment_version_id
                      AND item.publication_state <> 'PUBLISHED') THEN
                RAISE EXCEPTION 'Assessment needs required items and published item versions'
                    USING ERRCODE = '23514';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.guard_reviewed_assessment_items()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    old_parent uuid;
    new_parent uuid;
    reviewed_hash platform.content_hash;
BEGIN
    IF TG_OP <> 'INSERT' THEN old_parent := OLD.assessment_version_id; END IF;
    IF TG_OP <> 'DELETE' THEN new_parent := NEW.assessment_version_id; END IF;

    FOR reviewed_hash IN
        SELECT reviewed_content_hash
        FROM platform.assessment_version
        WHERE assessment_version_id IN (old_parent, new_parent)
        ORDER BY assessment_version_id
        FOR UPDATE
    LOOP
        IF reviewed_hash IS NOT NULL THEN
            RAISE EXCEPTION 'Reviewed assessment item set is immutable' USING ERRCODE = '23514';
        END IF;
    END LOOP;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.valid_adaptive_blueprint_configuration(config jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE bound jsonb; role_key text;
BEGIN
    IF jsonb_typeof(config) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
    IF config ? 'occupationBounds' THEN
        IF NOT config ?& ARRAY['name','occupationBounds']
            OR config - ARRAY['name','occupationBounds'] <> '{}'::jsonb
            OR jsonb_typeof(config -> 'name') IS DISTINCT FROM 'string'
            OR btrim(config ->> 'name') = '' THEN RETURN false; END IF;
        bound := config -> 'occupationBounds';
        IF jsonb_typeof(bound) IS DISTINCT FROM 'object'
            OR NOT bound ?& ARRAY['maxQuestions','timeLimitSeconds']
            OR bound - ARRAY['maxQuestions','timeLimitSeconds'] <> '{}'::jsonb
            OR jsonb_typeof(bound -> 'maxQuestions') IS DISTINCT FROM 'number'
            OR jsonb_typeof(bound -> 'timeLimitSeconds') IS DISTINCT FROM 'number' THEN RETURN false; END IF;
        IF (bound ->> 'maxQuestions') !~ '^[0-9]+$' OR (bound ->> 'timeLimitSeconds') !~ '^[0-9]+$'
            OR (bound ->> 'maxQuestions')::numeric NOT BETWEEN 1 AND 2147483647
            OR (bound ->> 'timeLimitSeconds')::numeric NOT BETWEEN 1 AND 2147483647 THEN RETURN false; END IF;
        IF char_length(btrim(config ->> 'name')) > 100
            OR (bound ->> 'timeLimitSeconds')::numeric < 30 * (bound ->> 'maxQuestions')::numeric
            OR (bound ->> 'timeLimitSeconds')::numeric > 120 * (bound ->> 'maxQuestions')::numeric THEN RETURN false; END IF;
        RETURN true;
    END IF;
    IF jsonb_typeof(config) IS DISTINCT FROM 'object'
        OR NOT config ?& ARRAY['name', 'exploration', 'roles']
        OR config - ARRAY['name', 'exploration', 'roles'] <> '{}'::jsonb
        OR jsonb_typeof(config -> 'name') IS DISTINCT FROM 'string'
        OR btrim(config ->> 'name') = ''
        OR jsonb_typeof(config -> 'roles') IS DISTINCT FROM 'object'
        OR config -> 'roles' = '{}'::jsonb THEN RETURN false; END IF;
    FOR role_key IN SELECT jsonb_object_keys(config -> 'roles') LOOP
        IF btrim(role_key) = '' OR role_key <> btrim(role_key) THEN RETURN false; END IF;
    END LOOP;
    FOR bound IN SELECT config -> 'exploration' UNION ALL SELECT value FROM jsonb_each(config -> 'roles') LOOP
        IF jsonb_typeof(bound) IS DISTINCT FROM 'object'
            OR NOT bound ?& ARRAY['maxQuestions', 'timeLimitSeconds']
            OR bound - ARRAY['maxQuestions', 'timeLimitSeconds'] <> '{}'::jsonb
            OR jsonb_typeof(bound -> 'maxQuestions') IS DISTINCT FROM 'number'
            OR jsonb_typeof(bound -> 'timeLimitSeconds') IS DISTINCT FROM 'number' THEN RETURN false; END IF;
        IF (bound ->> 'maxQuestions') !~ '^[0-9]+$' OR (bound ->> 'timeLimitSeconds') !~ '^[0-9]+$'
            OR (bound ->> 'maxQuestions')::numeric NOT BETWEEN 1 AND 2147483647
            OR (bound ->> 'timeLimitSeconds')::numeric NOT BETWEEN 1 AND 2147483647 THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION platform.validate_activity_requirements()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE activity_record platform.learning_activity%ROWTYPE;
BEGIN
    SELECT * INTO activity_record FROM platform.learning_activity WHERE activity_id = NEW.activity_id;
    IF NOT EXISTS (SELECT 1 FROM platform.activity_requirement WHERE activity_id = NEW.activity_id AND required)
        OR EXISTS (
            SELECT 1 FROM platform.module_assessment_binding binding
            WHERE binding.module_ref_id = activity_record.module_ref_id
            AND NOT EXISTS (SELECT 1 FROM platform.activity_requirement requirement
                WHERE requirement.activity_id = activity_record.activity_id
                AND requirement.assessment_version_id = binding.assessment_version_id)
        ) THEN
        RAISE EXCEPTION 'Activity must pin the complete module assessment binding with at least one required assessment' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.validate_adaptive_attempt_aggregate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE attempt platform.baseline_adaptive_attempt%ROWTYPE;
DECLARE answered integer;
DECLARE correct integer;
BEGIN
    SELECT * INTO STRICT attempt FROM platform.baseline_adaptive_attempt WHERE attempt_id = NEW.attempt_id;
    SELECT count(*), count(*) FILTER (WHERE is_correct) INTO answered, correct
        FROM platform.baseline_attempt_response WHERE attempt_id = attempt.attempt_id;
    IF (SELECT count(*) FROM platform.baseline_attempt_pool_item WHERE attempt_id = attempt.attempt_id) < attempt.max_questions
        OR NOT EXISTS (SELECT 1 FROM platform.baseline_attempt_item WHERE attempt_id = attempt.attempt_id AND position = 1)
        OR attempt.revision < answered::bigint + 1 THEN
        RAISE EXCEPTION 'Attempt requires pinned capacity, first item and response revision' USING ERRCODE = '23514';
    END IF;
    IF EXISTS (
        WITH expected AS (SELECT DISTINCT micro_skill_id FROM platform.baseline_adaptive_blueprint_skill
            WHERE blueprint_id = attempt.blueprint_id AND blueprint_version = attempt.blueprint_version
                AND (attempt.scope_policy = 'FULL_OCCUPATION_V2' OR attempt.target_role_id IS NULL OR role_id = attempt.target_role_id)),
        actual AS (SELECT micro_skill_id FROM platform.baseline_attempt_skill_state WHERE attempt_id = attempt.attempt_id)
        (SELECT * FROM expected EXCEPT SELECT * FROM actual) UNION ALL
        (SELECT * FROM actual EXCEPT SELECT * FROM expected)) THEN
        RAISE EXCEPTION 'Attempt skill scope must equal pinned role or deduplicated role union' USING ERRCODE = '23514';
    END IF;
    IF EXISTS (SELECT 1 FROM platform.baseline_attempt_skill_state skill
        WHERE skill.attempt_id = attempt.attempt_id AND (skill.answered_count <> (
            SELECT count(*) FROM platform.baseline_attempt_response response JOIN platform.baseline_attempt_item item
                USING (attempt_id, position) WHERE response.attempt_id = skill.attempt_id AND item.micro_skill_id = skill.micro_skill_id)
            OR skill.updated_at < attempt.started_at OR skill.updated_at >= attempt.deadline_at)) THEN
        RAISE EXCEPTION 'Provisional state must match accepted responses and server timing' USING ERRCODE = '23514';
    END IF;
    IF attempt.finished_at IS NOT NULL AND EXISTS (SELECT 1 FROM platform.baseline_attempt_response
        WHERE attempt_id = attempt.attempt_id AND accepted_at > attempt.finished_at) THEN
        RAISE EXCEPTION 'Completion cannot precede accepted responses' USING ERRCODE = '23514';
    END IF;
    IF attempt.state NOT IN ('SUBMITTED', 'AUTO_SUBMITTED') THEN
        IF EXISTS (SELECT 1 FROM platform.baseline_attempt_result WHERE attempt_id = attempt.attempt_id)
            OR EXISTS (SELECT 1 FROM platform.baseline_attempt_skill_result WHERE attempt_id = attempt.attempt_id)
            OR EXISTS (SELECT 1 FROM platform.baseline_mastery_evidence WHERE attempt_id = attempt.attempt_id) THEN
            RAISE EXCEPTION 'Only successful completion may produce results/mastery' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM platform.baseline_attempt_result result JOIN platform.outbox_event event
            ON event.event_id = result.mastery_event_id WHERE result.attempt_id = attempt.attempt_id
            AND result.result_status = attempt.state AND result.answered_count = answered AND result.correct_count = correct
            AND result.scored_at = attempt.finished_at AND event.aggregate_id = attempt.attempt_id)
        OR EXISTS (SELECT 1 FROM platform.baseline_attempt_skill_state state
            LEFT JOIN platform.baseline_attempt_skill_result result USING (attempt_id, micro_skill_id)
            LEFT JOIN platform.baseline_mastery_evidence evidence USING (attempt_id, micro_skill_id)
            WHERE state.attempt_id = attempt.attempt_id AND (result.attempt_id IS NULL OR evidence.attempt_id IS NULL
                OR result.mastery_mapping_version_id <> attempt.mastery_mapping_version_id
                OR result.finalized_at <> attempt.finished_at
                OR ROW(result.theta, result.standard_error) IS DISTINCT FROM ROW(state.theta, state.standard_error)
                OR ROW(evidence.theta, evidence.standard_error, evidence.estimated_mastery, evidence.mastery,
                    evidence.confidence_label, evidence.model_version_id, evidence.mastery_mapping_version_id,
                    evidence.parameter_set_id, evidence.emitted_at)
                    IS DISTINCT FROM ROW(result.theta, result.standard_error, result.estimated_mastery, result.mastery,
                        result.confidence_label, attempt.model_version_id, attempt.mastery_mapping_version_id,
                        attempt.parameter_set_id, attempt.finished_at))) THEN
        RAISE EXCEPTION 'Completion requires consistent immutable result, every skill and one mastery event' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.validate_baseline_assessment_series()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    candidate record;
    active record;
    working record;
BEGIN
    IF NEW.working_revision_id IS NOT NULL THEN
        SELECT organization_id, occupation_id, blueprint_id, state
        INTO working
        FROM platform.baseline_blueprint_working_revision
        WHERE working_revision_id = NEW.working_revision_id;
        IF NOT FOUND OR working.organization_id <> NEW.organization_id
            OR working.occupation_id <> NEW.occupation_id
            OR working.blueprint_id <> NEW.blueprint_id
            OR working.state <> 'OPEN' THEN
            RAISE EXCEPTION 'Working revision does not belong to the open baseline series'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.open_assessment_version_id IS NOT NULL THEN
        SELECT blueprint_id, blueprint_version, publication_state,
               baseline_candidate_state, reviewed_content_hash
        INTO candidate
        FROM platform.assessment_version
        WHERE assessment_version_id = NEW.open_assessment_version_id
          AND purpose = 'BASELINE';
        IF NOT FOUND OR candidate.blueprint_id <> NEW.blueprint_id
            OR candidate.blueprint_version IS DISTINCT FROM NEW.pending_blueprint_version
            OR candidate.publication_state <> 'DRAFT'
            OR candidate.baseline_candidate_state <> 'OPEN' THEN
            RAISE EXCEPTION 'Open assessment candidate does not match its pending blueprint'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.active_assessment_version_id IS NOT NULL THEN
        SELECT blueprint_id, publication_state INTO active
        FROM platform.assessment_version
        WHERE assessment_version_id = NEW.active_assessment_version_id
          AND purpose = 'BASELINE';
        IF NOT FOUND OR active.blueprint_id <> NEW.blueprint_id
            OR active.publication_state <> 'PUBLISHED' THEN
            RAISE EXCEPTION 'Active assessment does not belong to this baseline series'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.validate_baseline_assessment_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    blueprint_organization_id uuid;
    creator_organization_id uuid;
    reviewer_organization_id uuid;
BEGIN
    IF NEW.purpose <> 'BASELINE' OR NEW.blueprint_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT organization_id INTO blueprint_organization_id
    FROM platform.baseline_blueprint
    WHERE blueprint_id = NEW.blueprint_id;
    SELECT organization_id INTO creator_organization_id
    FROM platform.account
    WHERE account_id = NEW.created_by;
    IF blueprint_organization_id IS NULL
        OR blueprint_organization_id IS DISTINCT FROM creator_organization_id THEN
        RAISE EXCEPTION 'Baseline assessment creator is outside the blueprint organization'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.reviewed_by IS NOT NULL THEN
        SELECT organization_id INTO reviewer_organization_id
        FROM platform.account
        WHERE account_id = NEW.reviewed_by;
        IF blueprint_organization_id IS DISTINCT FROM reviewer_organization_id THEN
            RAISE EXCEPTION 'Baseline assessment reviewer is outside the blueprint organization'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.validate_baseline_blueprint_occupation_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    identity_record record;
    creator_organization_id uuid;
BEGIN
    SELECT identity.occupation_id, identity.organization_id
    INTO identity_record
    FROM platform.baseline_blueprint identity
    WHERE identity.blueprint_id = NEW.blueprint_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Baseline blueprint identity is missing'
            USING ERRCODE = '23503';
    END IF;

    IF identity_record.occupation_id IS DISTINCT FROM NEW.occupation_id THEN
        RAISE EXCEPTION 'Blueprint version occupation does not match its logical identity'
            USING ERRCODE = '23514';
    END IF;

    SELECT organization_id INTO creator_organization_id
    FROM platform.account
    WHERE account_id = NEW.created_by;

    IF identity_record.organization_id IS DISTINCT FROM creator_organization_id THEN
        RAISE EXCEPTION 'Blueprint version creator is outside the blueprint organization'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.validate_baseline_command_actor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    actor_organization_id uuid;
BEGIN
    SELECT organization_id INTO actor_organization_id
    FROM platform.account WHERE account_id = NEW.actor_id;
    IF actor_organization_id IS DISTINCT FROM NEW.organization_id THEN
        RAISE EXCEPTION 'Baseline command actor is outside the command organization'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.validate_baseline_management_actor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    actor_id uuid;
    actor_organization_id uuid;
BEGIN
    IF TG_TABLE_NAME = 'baseline_assessment_transition' THEN
        actor_id := NEW.actor_id;
    ELSIF TG_TABLE_NAME = 'baseline_blueprint_working_revision' THEN
        actor_id := NEW.updated_by;
    ELSE
        RAISE EXCEPTION 'Unsupported baseline management actor trigger table: %', TG_TABLE_NAME
            USING ERRCODE = '55000';
    END IF;

    SELECT organization_id INTO actor_organization_id
    FROM platform.account
    WHERE account_id = actor_id;

    IF actor_organization_id IS DISTINCT FROM NEW.organization_id THEN
        RAISE EXCEPTION 'Baseline management actor is outside the series organization'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.validate_irt_selection_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE previous_revision bigint; previous_set uuid;
BEGIN
    IF TG_OP='INSERT' THEN previous_revision=0; previous_set=NULL;
    ELSE previous_revision=OLD.selection_revision; previous_set=OLD.parameter_set_id; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.irt_parameter_promotion_command c JOIN platform.irt_parameter_set s USING (parameter_set_id,model_version_id)
        WHERE c.organization_id=NEW.organization_id AND c.question_bank_id=NEW.question_bank_id AND c.model_version_id=NEW.model_version_id
          AND c.selection_revision=NEW.selection_revision AND c.parameter_set_id=NEW.parameter_set_id
          AND c.actor_id=NEW.selected_by AND c.occurred_at=NEW.selected_at AND c.parameter_hash=s.parameter_hash
          AND c.expected_revision=previous_revision AND c.expected_parameter_set_id IS NOT DISTINCT FROM previous_set
    ) THEN RAISE EXCEPTION 'Effective selection requires matching immutable command receipt' USING ERRCODE = '23514'; END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.validate_pathway_approval()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.status IN ('APPROVED', 'PUBLISHED_CURRENT') AND NOT EXISTS (
        SELECT 1 FROM platform.pathway_approval approval
        WHERE approval.pathway_revision_id = NEW.pathway_revision_id AND approval.approved_hash = NEW.content_hash
    ) THEN
        RAISE EXCEPTION 'Exact revision approval is required' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform.validate_scoring_context()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM platform.assessment_version definition
        WHERE definition.assessment_version_id = NEW.assessment_version_id
        AND definition.pass_threshold = NEW.pass_threshold AND definition.scoring_version = NEW.scoring_version) THEN
        RAISE EXCEPTION 'Scoring context differs from pinned assessment' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$
